-- 2. Caja y stock de ejemplo (solo en negocios que tenían los productos de ejemplo)
delete from stock_conteos where producto_id in (select id from productos where nombre in ('Empanadas', 'Vacas', 'Abono orgánico', 'Café pergamino') and unidad in ('unidad', 'cabeza', 'bulto', 'kg'));
delete from stock_movimientos where producto_id in (select id from productos where nombre in ('Empanadas', 'Vacas', 'Abono orgánico', 'Café pergamino') and unidad in ('unidad', 'cabeza', 'bulto', 'kg'));
delete from caja_movimientos where concepto in ('Ventas del día', 'Pago de cliente', 'Combustible y jornales')
  and negocio_id in (select negocio_id from productos where nombre in ('Empanadas', 'Vacas', 'Abono orgánico', 'Café pergamino'));
delete from caja_dias where negocio_id in (select negocio_id from productos where nombre in ('Empanadas', 'Vacas', 'Abono orgánico', 'Café pergamino'))
  and not exists (select 1 from caja_movimientos m where m.negocio_id = caja_dias.negocio_id and m.dia = caja_dias.dia);
delete from productos where nombre in ('Empanadas', 'Vacas', 'Abono orgánico', 'Café pergamino') and unidad in ('unidad', 'cabeza', 'bulto', 'kg')
  and not exists (select 1 from stock_movimientos s where s.producto_id = productos.id);

-- 3. Servicios y recursos de ejemplo que ya no tienen citas
delete from servicio_recurso where servicio_id in (
  select id from servicios where nombre_en in ('Technical visit', 'Spraying', 'Harvest', 'Transport to collection point', 'Soil sampling')
    and not exists (select 1 from citas c where c.servicio_id = servicios.id));
delete from servicios where nombre_en in ('Technical visit', 'Spraying', 'Harvest', 'Transport to collection point', 'Soil sampling')
  and not exists (select 1 from citas c where c.servicio_id = servicios.id);
delete from disponibilidad where recurso_id in (
  select id from recursos where nombre in ('Cuadrilla A', 'Cuadrilla B', 'Tractor 2', 'Camión 1', 'Agrónomo')
    and not exists (select 1 from citas c where c.recurso_id = recursos.id)
    and not exists (select 1 from servicio_recurso sr where sr.recurso_id = recursos.id));
delete from recursos where nombre in ('Cuadrilla A', 'Cuadrilla B', 'Tractor 2', 'Camión 1', 'Agrónomo')
  and not exists (select 1 from citas c where c.recurso_id = recursos.id)
  and not exists (select 1 from servicio_recurso sr where sr.recurso_id = recursos.id);

-- 4. Negocio principal: nombre de demostración
update configuracion set valor = 'FieldFlow' where clave = 'negocio_nombre' and valor = 'FieldFlow Demo';
